<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {Icon} from '@packages/icon';import {strokeIconPaths} from '@/views/AgentWork/strokeIconPaths';import {agentWorkData} from '@/pinia/agentWork';import {usePhase1} from '@/pinia/phase1';import {phaseSkills,dateText} from './catalog';import MonitorTaskDialog from './MonitorTaskDialog.vue';import {taskRule} from './ruleLanguage';import type {P1SkillId} from '@/views/AgentWork/interface';import LegacyTasks from '@/views/AgentWork/views/dailyTasks.view.vue';
const route=useRoute();const router=useRouter();const work=agentWorkData();const s=usePhase1();const selectedId=ref('');const orderFilter=ref('');const search=ref('');const filter=ref('all');const showBackground=ref(false);const weatherFeedback=ref('');const weatherOrder=computed(()=>orders.value.find(o=>o.id===orderFilter.value)||orders.value[0]);
function weatherDemo(advance=false){const o=weatherOrder.value;if(!o)return;if(advance&&o.weatherEffectiveAt){s.advance(Math.max(0,(o.weatherEffectiveAt-s.now)/60000));weatherFeedback.value='已推进到预计生效时间（本地模拟）';}else weatherFeedback.value=s.weatherSample(o.id)||'天气事件已获取，直接生成异常，结果如下。';}
watch(()=>route.query.projectId,id=>{const project=work.projects.find(p=>p.id===id);if(project&&work.currentProjectId!==id)work.switchProject(project);},{immediate:true});
const legacy=computed(()=>route.query.scope==='legacy'||route.query.scope==='personal'||work.workspaceMode==='conversation'&&!route.query.projectId);const config=computed(()=>s.config(work.currentProjectId));const tasks=computed(()=>phaseSkills.filter(t=>config.value.selectedSkills.includes(t.id)));const task=computed(()=>phaseSkills.find(t=>t.id===selectedId.value));
watch([()=>route.query.taskId,()=>work.currentProjectId],()=>{selectedId.value=phaseSkills.find(t=>t.id===route.query.taskId)?.id||'';orderFilter.value=String(route.query.orderId||'');},{immediate:true});
const orders=computed(()=>s.orders.filter(o=>o.projectId===work.currentProjectId));
function enabled(id:string){const c=config.value;return id==='p1-weather'?c.weather.enabled:id==='p1-status'?c.fenceTargets.length>0&&c.statusUpdates.length>0:id==='p1-late'?c.lateDeparture.enabled||c.lateArrival.enabled:id==='p1-parking'?c.parking.enabled:id==='p1-offline'?c.offline.enabled:c.deviation.enabled;}
function taskLogs(id:string){return s.logs.filter(l=>l.projectId===work.currentProjectId&&l.taskId===id);}
function count(id:string){return taskLogs(id).filter(l=>['开始','结果','提醒','恢复','结束','失败'].includes(l.kind)).length;}
const visibleTasks=computed(()=>tasks.value.filter(t=>(!search.value||`${t.name} ${t.description}`.includes(search.value))&&(filter.value==='all'||enabled(t.id)===(filter.value==='running'))));
const results=computed(()=>taskLogs(selectedId.value).filter(l=>['开始','结果','提醒','恢复','结束','失败'].includes(l.kind)&&(!orderFilter.value||l.orderId===orderFilter.value)).slice().reverse().map(l=>{const logs=taskLogs(l.taskId).filter(x=>x.orderId===l.orderId);const pos=logs.findIndex(x=>x.id===l.id);const previous=logs.slice(0,pos).map((x,i)=>({x,i})).filter(({x})=>['开始','结果','提醒','恢复','结束','失败'].includes(x.kind)).at(-1)?.i??-1;return {...l,facts:logs.slice(0,pos+1).filter(x=>x.kind==='基础事件').at(-1)?.text,steps:logs.slice(previous+1,pos+1),order:orders.value.find(o=>o.id===l.orderId)};}));
function configure(){router.push({path:'/index/projects/detail',query:{projectId:work.currentProjectId,tab:'skills'}});}
function toggle(id:string){const c=s.config(work.currentProjectId);const on=enabled(id);c.resumeSettings??={};
 if(id==='p1-status'){if(on){c.resumeSettings.statusUpdates=[...c.statusUpdates];c.statusUpdates=[];}else c.statusUpdates=c.resumeSettings.statusUpdates||['loading','in_transit','arrived','completed'];}
 else if(id==='p1-late'){if(on){c.resumeSettings.lateDeparture=c.lateDeparture.enabled;c.resumeSettings.lateArrival=c.lateArrival.enabled;c.lateDeparture.enabled=false;c.lateArrival.enabled=false;}else{c.lateDeparture.enabled=c.resumeSettings.lateDeparture??true;c.lateArrival.enabled=c.resumeSettings.lateArrival??true;}}
 else if(id==='p1-weather')c.weather.enabled=!on;
 else c[id==='p1-parking'?'parking':id==='p1-offline'?'offline':'deviation'].enabled=!on;
 s.saveConfig(work.currentProjectId,c,c.version);}

const editingTask=ref<P1SkillId>();const legacyRef=ref<InstanceType<typeof LegacyTasks>>();
function selectMonitor(id:string){legacyRef.value?.clearSelection();selectedId.value=id;}
function monitorMatches(text:string,status:string,type:string){return tasks.value.filter(t=>type==='monitor'&&`${t.name} ${t.description} ${taskRule(config.value,t.id)}`.includes(text)&&(status==='all'||(status==='running'?enabled(t.id):status==='paused'?!enabled(t.id):false)));}
</script>
<template><LegacyTasks v-if="legacy"/><LegacyTasks v-else ref="legacyRef" :monitor-count="tasks.length" :monitor-running="tasks.filter(t=>enabled(t.id)).length" :monitor-selected="!!task" @select-legacy="selectedId=''"><template #monitor-cards="slot"><p v-if="slot.type==='monitor'&&!monitorMatches(slot.search,slot.status,slot.type).length" class="dt-empty">没有匹配的系统任务</p><article v-for="t in monitorMatches(slot.search,slot.status,slot.type)" :key="t.id" class="dt-task-card" :class="{selected:selectedId===t.id}"><button class="dt-task-main" :aria-label="`查看任务 ${t.name}`" :aria-pressed="selectedId===t.id" @click="selectMonitor(t.id)"><div class="dt-task-heading"><span class="dt-task-symbol"><Icon :svg="t.id==='p1-late'?strokeIconPaths.alarmClock:strokeIconPaths.zap" :size="17"/></span><h2>{{t.name}}</h2><span class="dt-badge" :class="{blue:enabled(t.id)}">{{enabled(t.id)?'已开启':'已暂停'}}</span></div><p class="dt-trigger">系统任务 · {{t.id==='p1-weather'?'天气消息触发 · 次日0点预计生效':t.id==='p1-late'?'定时 / 状态更新触发 · 时效与经过记录':'条件触发 · 收到订阅基础事件'}}</p><p class="dt-task-description" :title="t.description">{{t.description}}</p><p class="dt-task-description" :title="taskRule(config,t.id)">{{taskRule(config,t.id)}}</p></button><footer class="dt-task-footer"><div class="dt-task-meta"><span>{{count(t.id)}}条结果</span></div><div class="dt-task-actions"><button class="dt-icon" :aria-label="`编辑 ${t.name}`" title="编辑" @click="editingTask=t.id"><Icon :svg="strokeIconPaths.edit" :size="15"/></button><button class="dt-icon" :aria-label="`查看结果 ${t.name}`" title="查看执行结果" @click="selectMonitor(t.id)"><Icon :svg="strokeIconPaths.list" :size="15"/></button><button class="dt-icon" :aria-label="`${enabled(t.id)?'暂停':'开始'} ${t.name}`" @click="toggle(t.id)"><Icon :svg="enabled(t.id)?strokeIconPaths.pause:strokeIconPaths.play" :size="15"/></button></div></footer></article></template><template #monitor-panel><aside v-if="task" class="dt-run-panel" aria-label="任务运行面板"><header class="dt-run-header"><div class="dt-title"><Icon :svg="strokeIconPaths.bot" :size="16"/><h2>{{task.name}}</h2></div><div class="dt-actions"><button class="dt-background-toggle" :aria-expanded="showBackground" @click="showBackground=!showBackground">任务背景</button><button class="dt-icon" aria-label="关闭运行面板" @click="selectedId='' "><Icon :svg="strokeIconPaths.x" :size="16"/></button></div></header><div class="dt-run-body"><div class="dt-run-scroll" :key="task.id"><div class="dt-run-section-heading"><h3>执行结果 <span class="dt-secondary">{{results.length}}</span></h3><select v-model="orderFilter" aria-label="任务运单范围"><option value="">全部运单</option><option v-for="o in orders" :key="o.id" :value="o.id">{{o.id}}</option></select></div><div v-if="task.id==='p1-weather'" class="dt-run-context"><p>不发送车机提醒；有效天气事件直接生成异常，无研判参数。</p><p v-for="o in orders.filter(o=>!orderFilter||o.id===orderFilter)" :key="o.id">{{o.id}} · {{s.weatherState(o)}} · 预计{{dateText(o.weatherEffectiveAt)}} · 截止{{dateText(o.expiresAt)}}</p><button class="dt-button" @click="router.push({path:'/index/detail',query:{orderId:orderFilter||orders[0]?.id}})">进入运单详情</button><button class="dt-button" :disabled="!weatherOrder?.weatherEffectiveAt" @click="weatherDemo(true)">模拟推进至预计天气生效时间</button><button class="dt-button" @click="weatherDemo()">模拟暴雨预警消息</button><p role="status">{{weatherFeedback}}</p></div><p class="dt-secondary">V1.1 · 本地模拟；原始事件与纠正结果均保留。</p><section v-for="run in results" :key="run.id" class="dt-run"><header><div><strong>{{run.orderId}} · {{run.order?.plate}}</strong><small>{{dateText(run.at)}} · {{run.kind}}</small></div><span class="dt-badge" :class="{warning:run.kind==='失败'}">{{run.kind}}</span></header><p class="dt-run-result">{{run.text.replaceAll('S00','系统')}}</p><p v-if="run.facts&&run.kind==='结果'" class="dt-run-context">{{run.facts}}</p><button class="dt-text-button" @click="router.push({path:'/index/detail',query:{orderId:run.orderId}})">运单详情</button><details class="dt-run-steps"><summary>执行详情</summary><ol><li v-for="step in run.steps" :key="step.id"><Icon :svg="strokeIconPaths.check" :size="13"/><div><strong>{{step.kind}} · {{dateText(step.at)}}</strong><p>{{step.text}}</p></div></li></ol></details></section><div v-if="!results.length" class="dt-empty compact">暂无执行结果；创建及订阅信息在后续结果的执行详情中展示。</div></div><aside class="dt-background-rail" :class="{'is-open':showBackground}"><section class="dt-task-summary"><div class="dt-summary-title"><h2>{{task.name}}</h2><span class="dt-badge blue">{{enabled(task.id)?'已开启':'已暂停'}}</span></div><dl class="dt-summary-metrics"><div><dt>结果数量</dt><dd>{{count(task.id)}}条</dd></div><div><dt>配置版本</dt><dd>v{{config.version}}</dd></div></dl><p>{{task.description}}</p><p>{{taskRule(config,task.id)}}</p><p>创建后读取最新配置，最多监听72小时；结束信息保留为执行结果。</p></section></aside></div></aside></template></LegacyTasks><MonitorTaskDialog v-if="editingTask" :task-id="editingTask" :project-id="work.currentProjectId" @close="editingTask=undefined"/></template>
